<div class="row g-4"><div class="col-xl-8"><section class="card"><div class="card-body"><div class="section-heading"><h2 class="h4">Compras desta fatura</h2><a href="<?= H::escape($basePath.'/faturas/'.$invoice['id'].($showCancelled ? '' : '?exibir_cancelados=1')) ?>"><?= $showCancelled ? 'Ocultar cancelados' : 'Exibir cancelados' ?></a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Compra</th><th>Competência</th><th class="text-end">Valor</th></tr></thead><tbody>
<?php foreach ($items as $t): ?><tr><td><a href="<?= H::escape($basePath.'/movimentacoes/'.$t['id']) ?>"><?= H::escape($t['descricao']) ?></a><div class="small text-secondary"><?= H::escape($t['categoria']) ?><?= $t['numero_parcela'] ? ' · Parcela '.(int)$t['numero_parcela'] : '' ?><?= $t['status']==='cancelada' ? ' · Cancelada' : '' ?></div></td><td><?= H::date($t['data_competencia']) ?></td><td class="text-end"><?= Money::format((int)$t['valor_centavos']) ?><?php if ($t['estornado']): ?><div class="small text-secondary">Estornado: <?= Money::format((int)$t['estornado']) ?></div><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="3">Nenhuma compra nesta fatura.</td></tr><?php endif; ?></tbody></table></div><p class="small text-secondary mb-0">Total líquido: <?= Money::format((int)$invoice['total']) ?> · Pagamentos: <?= Money::format((int)$invoice['pago']) ?>. Créditos de estorno podem se referir a compras de outras faturas.</p></div></section>
<section class="card mt-4"><div class="card-body"><h2 class="h4">Pagamentos registrados</h2><?php if (!$payments): ?><p class="text-secondary">Nenhum pagamento até agora.</p><?php endif; ?><?php foreach ($payments as $p): ?><div class="list-row flex-wrap gap-2"><div><?= H::escape($p['conta_nome']) ?><small class="d-block text-secondary"><?= H::date($p['data_pagamento']) ?></small></div><div class="d-flex align-items-center gap-2"><strong><?= Money::format((int)$p['valor_centavos']) ?></strong><a class="btn btn-sm btn-outline-secondary" href="#editar-pagamento-<?= (int)$p['id'] ?>">Editar</a><form method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/pagamentos/'.$p['id'].'/excluir') ?>" data-confirm="Excluir este pagamento? O débito será removido da conta e o saldo da fatura será atualizado."><?= H::fields($csrfToken) ?><button class="btn btn-sm btn-outline-danger">Excluir</button></form></div></div>
<form id="editar-pagamento-<?= (int)$p['id'] ?>" method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/pagamentos/'.$p['id'].'/editar') ?>" class="row g-2 align-items-end mb-4" data-confirm="Salvar as alterações deste pagamento? Se mover para outra fatura, os saldos das duas faturas serão atualizados."><?= H::fields($csrfToken) ?>
