<div class="col-md-3"><label class="form-label" for="payment-account-<?= (int)$p['id'] ?>">Conta</label><select class="form-select" id="payment-account-<?= (int)$p['id'] ?>" name="conta_id" required><?php foreach ($accounts as $account): ?><option value="<?= (int)$account['id'] ?>" <?= (int)$account['id']===(int)$p['conta_id'] ? 'selected' : '' ?>><?= H::escape($account['nome']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><label class="form-label" for="payment-amount-<?= (int)$p['id'] ?>">Valor (R$)</label><input class="form-control" id="payment-amount-<?= (int)$p['id'] ?>" name="valor" inputmode="decimal" required value="<?= H::escape(number_format((int)$p['valor_centavos']/100,2,'.','')) ?>"></div>
<div class="col-md-2"><label class="form-label" for="payment-date-<?= (int)$p['id'] ?>">Data</label><input class="form-control" id="payment-date-<?= (int)$p['id'] ?>" name="data" type="date" max="<?= date('Y-m-d') ?>" required value="<?= H::escape($p['data_pagamento']) ?>"></div><div class="col-md-2"><button class="btn btn-sm btn-outline-secondary w-100">Salvar</button></div></form><?php endforeach; ?></div></section></div>
