<?php if ($remaining>0): ?><p class="text-secondary">Você pode pagar o total ou uma parte. O primeiro pagamento fecha a fatura.</p><form method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/pagar') ?>" class="vstack gap-3"><?= H::fields($csrfToken) ?>
<div><label for="pay-account" class="form-label">Conta de pagamento</label><select id="pay-account" name="conta_id" class="form-select" required><option value="">Selecione</option><?php foreach ($accounts as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)($old['conta_id'] ?? $invoice['conta_pagamento_id'])===(int)$a['id'] ? 'selected' : '' ?>><?= H::escape($a['nome']) ?></option><?php endforeach; ?></select></div>
<div><label for="pay-amount" class="form-label">Valor (R$)</label><input id="pay-amount" name="valor" class="form-control" inputmode="decimal" required value="<?= H::escape($old['valor'] ?? number_format($remaining/100,2,'.','')) ?>"></div>
<div><label for="pay-date" class="form-label">Data do pagamento</label><input id="pay-date" name="data" class="form-control" type="date" required max="<?= date('Y-m-d') ?>" value="<?= H::escape($old['data'] ?? date('Y-m-d')) ?>"></div><button class="btn btn-uai-primary">Registrar pagamento</button></form><?php else: ?><p class="text-secondary">Os pagamentos e as compras permanecem disponíveis para consulta.</p><?php endif; ?>
<?php if ($invoice['status']==='aberta'): ?><form class="mt-3" method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/fechar') ?>" data-confirm="Fechar a fatura? Novas compras não poderão ser adicionadas a ela."><?= H::fields($csrfToken) ?><button class="btn btn-outline-secondary w-100">Fechar fatura</button></form><?php elseif ($invoice['status']==='fechada'): ?><p class="small text-secondary mt-3 mb-2">Reabra para adicionar compras ou corrigir a fatura. Os pagamentos registrados permanecem na conta.</p><form method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/reabrir') ?>"><?= H::fields($csrfToken) ?><button class="btn btn-outline-secondary w-100">Reabrir fatura</button></form><?php endif; ?></div></section></div></div>

<?php if($remaining<0): ?><section class="card mt-4"><div class="card-body"><h2 class="h4">Usar crédito em outra fatura</h2><p class="text-secondary">Transporte <?= Money::format(-$remaining) ?> para outra fatura do mesmo cartão, inclusive uma já fechada ou paga.</p><form method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/credito') ?>" class="d-flex gap-3 align-items-end flex-wrap" data-confirm="Transportar este crédito para outra fatura? Os saldos das duas faturas serão alterados."><?= H::fields($csrfToken) ?><div><label class="form-label" for="credit-month">Mês de fechamento de destino</label><input id="credit-month" type="month" name="mes" class="form-control" required value="<?= H::escape(\App\Core\FinancialDate::shift($invoice['competencia'],1)) ?>"></div><button class="btn btn-uai-primary">Transportar crédito</button></form></div></section><?php endif; ?>
<form method="post" action="<?= H::escape($basePath.'/faturas/'.$invoice['id'].'/excluir') ?>" class="mt-4" data-confirm="Excluir esta fatura permanentemente? Suas compras, pagamentos e vínculos de crédito serão removidos; os saldos da conta, do cartão e de outras faturas podem mudar."><?= H::fields($csrfToken) ?><button class="btn btn-outline-danger">Excluir fatura</button></form>
<?php if($credits): ?><section class="card mt-4"><div class="card-body"><h2 class="h4">Créditos entre faturas</h2><?php foreach($credits as $credit): ?><p><?= (int)$credit['origem_id']===(int)$invoice['id'] ? 'Enviado para' : 'Recebido de' ?> <a href="<?= H::escape($basePath.'/faturas/'.((int)$credit['origem_id']===(int)$invoice['id'] ? $credit['destino_id'] : $credit['origem_id'])) ?>">outra fatura</a>: <?= Money::format((int)$credit['valor_centavos']) ?></p><?php endforeach; ?></div></section><?php endif; ?>
